        if len(preds) == len(outputs):
            correct = sum(1 for p, o in zip(preds, outputs) if p == list(o))
            score = correct / len(outputs)
            if score >= 1.0:
                return {"value": 1.0}
            return {"value": score,
                    "message": f"Score={score:.3f}: {correct}/{len(outputs)} correct (direct answers)."}

